package de.teamlapen.faction.common.core;

import de.teamlapen.faction.api.util.REFERENCE;
import de.teamlapen.faction.api.world.entities.extensions.IEntity;
import de.teamlapen.faction.common.factions.FactionPlayerHandler;
import de.teamlapen.faction.common.factions.lord.LordPlayer;
import de.teamlapen.faction.common.factions.neutral.NeutralPlayer;
import de.teamlapen.faction.common.factions.skills.RefinementHandler;
import de.teamlapen.faction.common.factions.tasks.TaskManager;
import de.teamlapen.faction.common.util.AttachmentSynchronization;
import de.teamlapen.faction.common.world.attachments.LevelDamage;
import de.teamlapen.sync.api.IAttachmentSync;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.neoforge.attachment.AttachmentType;
import net.neoforged.neoforge.attachment.IAttachmentHolder;
import net.neoforged.neoforge.registries.DeferredHolder;
import net.neoforged.neoforge.registries.DeferredRegister;
import net.neoforged.neoforge.registries.NeoForgeRegistries;

public class FactionAttachments {
    public static final DeferredRegister<AttachmentType<?>> ATTACHMENT_TYPES = DeferredRegister.create(NeoForgeRegistries.Keys.ATTACHMENT_TYPES, REFERENCE.MOD_ID);

    public static final DeferredHolder<AttachmentType<?>, AttachmentType<FactionPlayerHandler>> FACTION_PLAYER_HANDLER = ATTACHMENT_TYPES.register(de.teamlapen.faction.api.FactionAttachments.Keys.FACTION_PLAYER_HANDLER.getPath(), () -> syncAttachment(new FactionPlayerHandler.AttachmentOptions()).copyOnDeath().build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<NeutralPlayer>> NEUTRAL_PLAYER = ATTACHMENT_TYPES.register(de.teamlapen.faction.api.FactionAttachments.Keys.NEUTRAL_PLAYER.getPath(), () -> syncAttachment(new NeutralPlayer.AttachmentOptions()).copyOnDeath().build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<LevelDamage>> LEVEL_DAMAGE = ATTACHMENT_TYPES.register(de.teamlapen.faction.api.FactionAttachments.Keys.DAMAGE_HANDLER.getPath(), () -> AttachmentType.builder(new LevelDamage.Factory()).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<TaskManager>> TASK_MANAGER = ATTACHMENT_TYPES.register(de.teamlapen.faction.api.FactionAttachments.Keys.TASK_MANAGER.getPath(), () -> AttachmentType.builder(new TaskManager.Factory()).serialize(new TaskManager.Serializer()).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<RefinementHandler>> REFINEMENT_HANDLER = ATTACHMENT_TYPES.register(de.teamlapen.faction.api.FactionAttachments.Keys.REFINEMENT_HANDLER.getPath(), () -> syncAttachment(new RefinementHandler.AttachmentOptions()).build());
    public static final DeferredHolder<AttachmentType<?>, AttachmentType<LordPlayer>> LORD_PLAYER = ATTACHMENT_TYPES.register(de.teamlapen.faction.api.FactionAttachments.Keys.LORD_PLAYER.getPath(), () -> syncAttachment(new LordPlayer.AttachmentOptions()).copyOnDeath().build());

    static void register(IEventBus bus) {
        ATTACHMENT_TYPES.register(bus);
    }

    private static <T extends IAttachmentSync & IEntity, Z extends IAttachmentHolder> AttachmentType.Builder<T> syncAttachment(AttachmentSynchronization<T, Z> options) {
        return AttachmentType.builder(options).serialize(options).sync(options);
    }
}

package de.teamlapen.faction.common.factions.skills;

import de.teamlapen.faction.api.FactionDataComponents;
import de.teamlapen.faction.api.FactionRegistries;
import de.teamlapen.faction.api.factions.IFaction;
import de.teamlapen.faction.api.factions.actions.IAction;
import de.teamlapen.faction.api.factions.skills.*;
import de.teamlapen.faction.api.tags.FactionTags;
import de.teamlapen.faction.api.world.entities.player.IFactionPlayer;
import de.teamlapen.faction.common.core.ModRegistries;
import net.minecraft.core.Holder;
import net.minecraft.core.component.DataComponentMap;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceKey;
import net.minecraft.tags.TagKey;
import net.minecraft.world.entity.ai.attributes.Attribute;
import net.minecraft.world.entity.ai.attributes.AttributeInstance;
import net.minecraft.world.entity.ai.attributes.AttributeModifier;
import net.minecraft.world.entity.player.Player;
import org.jetbrains.annotations.Nullable;

import java.util.*;

/**
 * Default implementation of ISkill. Handles entity modifiers and actions
 */
public class Skill<T extends IFactionPlayer<T> & ISkillPlayer<T>> implements ISkill<T> {

    private final String descriptionId;
    private final Holder.Reference<ISkill<?>> builtInRegistryHolder;

    private final Map<Holder<Attribute>, SkillAttributeHolder> attributeModifierMap;

    public Skill(SkillProperties<T> properties) {
        this.builtInRegistryHolder = ModRegistries.SKILLS.createIntrusiveHolder(this);
        this.descriptionId = properties.effectiveNameId();
        this.attributeModifierMap = properties.attributes();

        //noinspection unchecked
        BuiltInRegistries.DATA_COMPONENT_INITIALIZERS.add((ResourceKey<ISkill<T>>) (Object) properties.skillIdOrThrow(), properties.finalizeInitializer(Component.translatable(properties.effectiveNameId())));
    }

    public DataComponentMap components() {
        return this.builtInRegistryHolder.components();
    }

    @Override
    public Component getName() {
        return this.components().getOrDefault(FactionDataComponents.SKILL_NAME, Component.empty());
    }

    @Override
    public @Nullable Component getDescription() {
        return this.components().get(FactionDataComponents.SKILL_DESCRIPTION);
    }

    @Override
    public TagKey<? extends IFaction<?>> factions() {
        return this.components().getOrDefault(FactionDataComponents.SKILL_FACTIONS, FactionTags.ALL_FACTIONS);
    }

    @Override
    public String getDescriptionId() {
        return this.descriptionId;
    }

    @Override
    public final void onDisable(T player) {
        removeAttributesModifiersFromEntity(player.asEntity());
        player.getActionHandler().relockActionHolder(getActions());
        if (IFaction.is(player.getFaction(), this.factions())) {
            onDisabled(player);
        } else {
            throw new IllegalArgumentException("Faction player instance is of wrong class " + player.getClass() + " for action " + FactionRegistries.SKILL.get().getKey(this));
        }
    }

    @Override
    public final void onEnable(T player) {
        applyAttributesModifiersToEntity(player.asEntity());

        if (IFaction.is(player.getFaction(), this.factions())) {
            player.getActionHandler().unlockActionHolder(getActions());
            onEnabled(player);
        } else {
            throw new IllegalArgumentException("skill is not allowed for player for skill " + FactionRegistries.SKILL.get().getKey(this));
        }
    }

    /**
     * Called when the skill is being disabled.
     */
    protected void onDisabled(T player) {
        var consumer = components().get(FactionDataComponents.SKILL_DISABLE_CONSUMABLE);
        if (consumer != null) {
            consumer.value().accept(player);
        }
    }

    /**
     * Called when the skill is being enabled
     */
    protected void onEnabled(T player) {
        var consumer = components().get(FactionDataComponents.SKILL_ENABLE_CONSUMABLE);
        if (consumer != null) {
            consumer.value().accept(player);
        }
    }

    @Override
    public Holder<? extends IAction<T>> getAction() {
        //noinspection unchecked
        return (Holder<? extends IAction<T>>) this.components().get(FactionDataComponents.SKILL_ACTION);
    }

    @Override
    public List<Holder<? extends IAction<T>>> getActions() {
        //noinspection unchecked
        return (List<Holder<? extends IAction<T>>>) this.components().getOrDefault(FactionDataComponents.SKILL_ACTIONS, List.of());
    }

    private void applyAttributesModifiersToEntity(Player player) {
        for (Map.Entry<Holder<Attribute>, SkillAttributeHolder> entry : this.attributeModifierMap.entrySet()) {
            AttributeInstance instance = player.getAttribute(entry.getKey());

            if (instance != null) {
                AttributeModifier attributeModifier = entry.getValue().create();
                instance.addOrReplacePermanentModifier(attributeModifier);
            }
        }
    }

    private void removeAttributesModifiersFromEntity(Player player) {
        for (Map.Entry<Holder<Attribute>, SkillAttributeHolder> entry : this.attributeModifierMap.entrySet()) {
            AttributeInstance attribute = player.getAttribute(entry.getKey());

            if (attribute != null) {
                attribute.removeModifier(entry.getValue().skillId());
            }
        }
    }

    @Override
    public int getSkillPointCost() {
        return this.components().getOrDefault(FactionDataComponents.SKILL_COST, 0);
    }

    @Override
    public SkillTreeRequirement allowedSkillTrees() {
        return Objects.requireNonNull(this.components().get(FactionDataComponents.SKILL_TREE_REQUIREMENT));
    }
}

package de.teamlapen.faction.common.factions.skills;

import com.mojang.serialization.Codec;
import de.teamlapen.faction.api.FactionRegistries;
import de.teamlapen.faction.api.factions.skills.*;
import de.teamlapen.faction.api.util.FIdentifier;
import de.teamlapen.faction.api.util.SafeCast;
import de.teamlapen.faction.api.world.entities.player.IFactionPlayer;
import de.teamlapen.faction.common.core.FactionAdvancements;
import de.teamlapen.faction.common.core.FactionEffects;
import de.teamlapen.faction.common.core.FactionStats;
import de.teamlapen.faction.common.core.ModRegistries;
import de.teamlapen.faction.common.event.FactionEventFactory;
import de.teamlapen.faction.common.util.collections.CollectionUtil;
import de.teamlapen.faction.common.util.collections.LiveMap;
import de.teamlapen.sync.PropertySync;
import net.minecraft.core.Holder;
import net.minecraft.resources.RegistryFixedCodec;
import net.minecraft.server.level.ServerPlayer;
import org.apache.commons.lang3.tuple.Pair;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

import java.util.*;
import java.util.stream.Collectors;

public class SkillHandler<T extends IFactionPlayer<T> & ISkillPlayer<T>> extends PropertySync implements ISkillHandler<T> {
    private final static Logger LOGGER = LogManager.getLogger();
    private final Map<Holder<ISkillTree>, List<Holder<? extends ISkill<T>>>> enabledSkills = new HashMap<>();
    private final LiveMap<Holder<? extends ISkill<T>>> skills = new LiveMap<>(enabledSkills);
    private final T player;
    private final SkillPoints skillPoints = new SkillPoints();
    private final Set<Holder<ISkillTree>> unlockedTrees = new LinkedHashSet<>();

    public SkillHandler(T player) {
        this.player = player;
    }

    @Override
    public void sync() {
        this.player.sync();
    }

    public SkillTreeGraph graph() {
        return SkillTreeGraphs.get(this.player.asEntity().level());
    }

    public Optional<Pair<Holder<ISkillTree>, SkillTreeGraph.Entry>> anyLastSegment() {
        SkillTreeGraph graph = graph();
        return unlockedTrees.stream().flatMap(s -> graph.tree(s).flatMap(x -> x.anyLastSegment(this::isSegmentEnabled)).map(x -> Pair.of(s, x)).stream()).findAny();
    }

    /**
     * Collects every skill that can currently be unlocked across all unlocked trees, i.e. every skill for which
     * {@link #canSkillBeEnabled(Holder, Holder)} returns {@link Result#OK}.
     */
    public List<Pair<Holder<ISkillTree>, Holder<? extends ISkill<T>>>> unlockableSkills() {
        SkillTreeGraph graph = graph();
        List<Pair<Holder<ISkillTree>, Holder<? extends ISkill<T>>>> unlockable = new ArrayList<>();
        for (Holder<ISkillTree> tree : this.unlockedTrees) {
            graph.tree(tree).ifPresent(x -> {
                for (SkillTreeGraph.Entry entry : x.entries()) {
                    for (Holder<? extends ISkill<?>> skill : entry.skills()) {
                        if (canSkillBeEnabled(skill, tree) == Result.OK) {
                            Holder<? extends ISkill<T>> typed = SafeCast.cast(skill);
                            unlockable.add(Pair.of(tree, typed));
                        }
                    }
                }
            });
        }
        return unlockable;
    }

    @Override
    public Result canSkillBeEnabled(Holder<? extends ISkill<?>> skill, Holder<ISkillTree> skillTree) {
        var preResult = FactionEventFactory.fireSkillUnlockCheckEvent(this.player, skill);
        if (preResult != null) {
            return preResult;
        }

        if (player.asEntity().getEffect(FactionEffects.OBLIVION) != null) {
            return Result.LOCKED_BY_PLAYER_STATE;
        }
        if (isSkillEnabled(skill)) {
            return Result.ALREADY_ENABLED;
        }
        if (!this.unlockedTrees.contains(skillTree)) {
            return Result.NOT_FOUND;
        }
        Optional<SkillTreeGraph.Entry> segment = graph().tree(skillTree).flatMap(x -> x.entryForSkill(skill));
        if (segment.isPresent()) {
            if (isSegmentLocked(segment.get())) {
                return Result.LOCKED_BY_OTHER_NODE;
            }
            if (segment.get().isRoot() || segment.get().parents().stream().anyMatch(this::isSegmentEnabled)) {
                if (getLeftSkillPoints(skillTree) >= skill.value().getSkillPointCost()) {
                    return isSegmentEnabled(segment.get()) ? Result.OTHER_NODE_SKILL : Result.OK;//If another skill in that segment is already enabled this one cannot be enabled
                } else {
                    return Result.NO_POINTS;
                }

            } else {
                return Result.PARENT_NOT_ENABLED;
            }
        } else {
            LOGGER.warn("Segment for skill {} could not be found", skill);
            return Result.NOT_FOUND;
        }
    }

    @Override
    public Result canSkillBeEnabled(Holder<? extends ISkill<?>> skill) {
        return treeForSkill(skill).map(s -> canSkillBeEnabled(skill, s)).orElse(Result.NOT_FOUND);
    }

    @Override
    public void disableSkill(Holder<? extends ISkill<T>> skill) {
        treeForSkill(SafeCast.cast(skill)).ifPresent(tree -> disableSkill(skill, tree));
    }

    @Override
    public void enableSkill(Holder<? extends ISkill<T>> skill) {
        treeForSkill(SafeCast.cast(skill)).ifPresent(tree -> enableSkill(skill, tree));
    }

    private Optional<Holder<ISkillTree>> treeForSkill(Holder<? extends ISkill<?>> skill) {
        return graph().entryForSkill(this.unlockedTrees, skill).map(x -> x.segment().value().tree());
    }

    public void disableAllSkills() {
        for (Map.Entry<Holder<ISkillTree>, List<Holder<? extends ISkill<T>>>> entry : enabledSkills.entrySet()) {
            for (Holder<? extends ISkill<T>> skill : entry.getValue()) {
                FactionEventFactory.fireSkillDisabledEvent(player, skill);
                skill.value().onDisable(player);
            }
        }
        for (var entry : enabledSkills.entrySet()) {
            Set<Holder<? extends ISkill<?>>> rootSkills = new HashSet<>(rootSkills(entry.getKey()));
            entry.getValue().removeIf(x -> !rootSkills.contains(x));
        }
    }

    private List<Holder<? extends ISkill<?>>> rootSkills(Holder<ISkillTree> tree) {
        return graph().tree(tree).stream().flatMap(x -> x.roots().stream()).flatMap(x -> x.skills().stream()).toList();
    }

    @Override
    public void disableSkill(Holder<? extends ISkill<T>> skill, Holder<ISkillTree> tree) {
        if (enabledSkills.containsKey(tree) && enabledSkills.get(tree).remove(skill)) {
            FactionEventFactory.fireSkillDisabledEvent(player, skill);
            skill.value().onDisable(player);
            player.sync();
        }
    }

    @Override
    public void enableSkill(Holder<? extends ISkill<T>> skill, Holder<ISkillTree>  tree, boolean fromLoading) {
        List<Holder<? extends ISkill<T>>> skills = this.enabledSkills.computeIfAbsent(tree, x -> new ArrayList<>());
        if (!skills.contains(skill)) {
            FactionEventFactory.fireSkillEnableEvent(player, skill, tree, fromLoading);
            skill.value().onEnable(player);
            skills.add(skill);
            if (!fromLoading) {
                this.player.asEntity().awardStat(FactionStats.SKILL_UNLOCKED.get().get(skill.value()));
            }
            //noinspection ConstantValue
            if (this.player.asEntity() instanceof ServerPlayer serverPlayer && serverPlayer.connection != null) {
                FactionAdvancements.TRIGGER_SKILL_UNLOCKED.get().trigger(serverPlayer, skill.value());
            }
            player.sync();
        }

    }

    @Override
    public void updateUnlockedSkillTrees(Collection<Holder<ISkillTree>> skillTrees) {
        List<Holder<ISkillTree>> removedTrees = this.unlockedTrees.stream().filter(x -> !skillTrees.contains(x)).toList();
        removedTrees.forEach(this::lockSkillTree);
        skillTrees.stream().filter(x -> !this.unlockedTrees.contains(x)).forEach(this::unlockSkillTree);
    }

    private void unlockSkillTree(Holder<ISkillTree> tree) {
        this.unlockedTrees.add(tree);
        rootSkills(tree).forEach(x -> enableSkill(SafeCast.cast(x), tree, true));
    }

    private void lockSkillTree(Holder<ISkillTree> tree) {
        var enabledSkills = new ArrayList<>(this.enabledSkills.getOrDefault(tree, Collections.emptyList()));
        for (Holder<? extends ISkill<T>> enabledSkill : enabledSkills) {
            if (enabledSkill.value().allowedSkillTrees().is(tree)) {
                this.disableSkill(enabledSkill, tree);
            }
        }
        this.unlockedTrees.remove(tree);
    }

    public Collection<Holder<ISkillTree>> unlockedSkillTrees() {
        return Collections.unmodifiableCollection(this.unlockedTrees);
    }

    @Override
    public int getLeftSkillPoints(Holder<ISkillTree> tree) {
        if (this.skillPoints.ignoreSkillPointLimit(this.player, tree)) {
            return Integer.MAX_VALUE;
        }
        return Math.max(0, this.skillPoints.getSkillPoints(this.player, tree) - this.enabledSkills.entrySet().stream().filter(x -> x.getKey().is(tree.value().skillPointTag())).flatMap(s -> s.getValue().stream()).map(Holder::value).mapToInt(ISkill::getSkillPointCost).sum());
    }

    public void reset() {
        disableAllSkills();
        this.unlockedTrees.clear();
    }

    public T getPlayer() {
        return player;
    }

    public boolean noSkillEnabled() {
        var defaultSkills = this.unlockedTrees.stream().collect(Collectors.toMap(x -> x, this::rootSkills));
        //noinspection SuspiciousMethodCalls
        return this.enabledSkills.isEmpty() || this.enabledSkills.entrySet().stream().allMatch(x -> defaultSkills.containsKey(x.getKey()) && new HashSet<>(defaultSkills.get(x.getKey())).containsAll(x.getValue()));
    }

    public boolean isSegmentEnabled(SkillTreeGraph.Entry segment) {
        return segment.skills().stream().anyMatch(this::isSkillEnabled);
    }

    public boolean isSegmentLocked(SkillTreeGraph.Entry segment) {
        return graph().lockingSegments(segment).stream().flatMap(x -> x.skills().stream()).anyMatch(this::isSkillEnabled);
    }

    @SuppressWarnings("SuspiciousMethodCalls")
    @Override
    public boolean areSkillsEnabled(Collection<Holder<? extends ISkill<?>>> skill) {
        return skills.containsAll(skill);
    }

    @Override
    public boolean isSkillEnabled(Holder<? extends ISkill<?>> skill) {
        return this.skills.contains(skill);
    }

    @SuppressWarnings("SuspiciousMethodCalls")
    @SafeVarargs
    public final boolean isAnySkillEnabled(Holder<? extends ISkill<?>>... skill) {
        return Arrays.stream(skill).anyMatch(skills::contains);
    }

    private static final Codec<Map<Holder<ISkillTree>, List<Holder<? extends ISkill<?>>>>> ENABLED_SKILLS_CODEC = Codec.simpleMap(ISkillTree.CODEC, ISkill.CODEC.listOf().xmap(x -> (List<Holder<? extends ISkill<?>>>)new ArrayList<>(x), x -> x), ModRegistries.SKILLS).codec();

    @Override
    protected void registerProperties() {
        this.registerProperty(FIdentifier.mod("unlocked_trees")).set(RegistryFixedCodec.create(FactionRegistries.Keys.SKILL_TREE)).provider(() -> this.unlockedTrees).commonLoader(x -> CollectionUtil.updateCollection(this.unlockedTrees, x)).register();
        this.registerProperty(FIdentifier.mod("skills")).simple(SafeCast.<Codec<Map<Holder<ISkillTree>, List<Holder<? extends ISkill<T>>>>>>cast(ENABLED_SKILLS_CODEC)).defaultValue(HashMap::new).provider(() -> this.enabledSkills).commonLoader(map -> {
            var old = new HashSet<>(this.skills);
            this.enabledSkills.clear();
            this.enabledSkills.putAll(map);
            return CollectionUtil.checkCollection(old, this.skills, x -> x.value().onDisable(this.player), x -> x.value().onEnable(this.player));
        }).register();
    }

    public void resetSkills() {
        disableAllSkills();
    }

    public static class SkillPoints {
        private final List<ISkillPointProvider> provider;

        public SkillPoints() {
            this.provider = FactionRegistries.SKILL_POINT_PROVIDER.get().stream().toList();
        }

        public int getSkillPoints(IFactionPlayer<?> factionPlayer, Holder<ISkillTree> tree) {
            return this.provider.stream().mapToInt(x -> Math.max(0, x.getSkillPoints(factionPlayer, tree))).sum();
        }

        public boolean ignoreSkillPointLimit(IFactionPlayer<?> factionPlayer, Holder<ISkillTree> tree) {
            return this.provider.stream().anyMatch(l -> l.ignoreSkillPointLimit(factionPlayer, tree));
        }
    }
}

package de.teamlapen.faction.common.util;

import de.teamlapen.faction.api.world.entities.extensions.IEntity;
import de.teamlapen.sync.BaseAttachmentSyncHandler;
import de.teamlapen.sync.api.IAttachmentSync;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.attachment.IAttachmentHolder;
import net.neoforged.neoforge.attachment.IAttachmentSerializer;
import org.jetbrains.annotations.NotNull;

public abstract class AttachmentSynchronization<T extends IAttachmentSync & IEntity, Z extends IAttachmentHolder> extends BaseAttachmentSyncHandler<@NotNull T> implements IAttachmentSerializer<T> {

    @Override
    public T read(IAttachmentHolder holder, ValueInput input) {
        T attachment = apply(holder);
        attachment.deserialize(input);
        return attachment;
    }

    protected abstract T create(Z player);

    @Override
    public boolean write(T attachment, ValueOutput output) {
        attachment.serialize(output);
        return true;
    }

    public static abstract class PlayerOptions<T extends IAttachmentSync & IEntity> extends AttachmentSynchronization<T, Player> {
        @Override
        public T apply(IAttachmentHolder holder) {
            if (holder instanceof net.minecraft.world.entity.player.Player player) {
                return create(player);
            }
            throw new IllegalArgumentException("Cannot create attachment for holder " + holder.getClass() + ". Expected Player");
        }
    }
}

package de.teamlapen.faction.common.util.collections;

import com.google.common.collect.Sets;
import it.unimi.dsi.fastutil.ints.IntComparator;

import java.util.*;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Function;

public class CollectionUtil {

    /**
     * @implNote this only checks for updates in the keys, not the values. It assumes the values are immutable.
     */
    public static <TKey, TEntity> boolean updateCollection(Map<TKey, TEntity> oldMap, Map<TKey, TEntity> newMap, BiConsumer<TKey, TEntity> removeAction, BiConsumer<TKey, TEntity> addAction) {
        boolean changes = false;
        for (TKey tKey : new ArrayList<>(Sets.difference(oldMap.keySet(), newMap.keySet()))) {
            removeAction.accept(tKey, oldMap.get(tKey));
            oldMap.remove(tKey);
            changes = true;
        }

        for (TKey tKey : new ArrayList<>(Sets.difference(newMap.keySet(), oldMap.keySet()))) {
            oldMap.put(tKey, newMap.get(tKey));
            addAction.accept(tKey, newMap.get(tKey));
            changes = true;
        }

        oldMap.putAll(newMap);

        return changes;
    }

    public static <TKey, TEntity> boolean updateCollection(Map<TKey, TEntity> oldMap, Map<TKey, TEntity> newMap) {
        return updateCollection(oldMap, newMap, (k, v) -> {}, (k, v) -> {});
    }

    public static <TEntity> boolean updateCollection(Collection<TEntity> oldCollection, Collection<TEntity> newCollection) {
        return updateCollection(oldCollection, newCollection,_ -> {}, _ -> {});
    }

    /**
     * {@code oldCollection} is mutated in place: elements missing from {@code newCollection}
     * are removed from it, and elements missing from {@code oldCollection} are added to it.
     */
    public static <TEntity> boolean updateCollection(Collection<TEntity> oldCollection, Collection<TEntity> newCollection, Consumer<TEntity> removeAction, Consumer<TEntity> addAction) {
        boolean changed = false;
        for (TEntity entity : difference(oldCollection, newCollection)) {
            removeAction.accept(entity);
            oldCollection.remove(entity);
            changed = true;
        }

        for (TEntity entity : difference(newCollection, oldCollection)) {
            oldCollection.add(entity);
            addAction.accept(entity);
            changed = true;
        }

        return changed;
    }

    public static <TEntity> boolean checkCollection(Collection<TEntity> oldMap, Collection<TEntity> newMap) {
        return checkCollection(oldMap, newMap, _ -> {}, _ -> {});
    }

    public static <TEntity> boolean checkCollection(Collection<TEntity> oldCollection, Collection<TEntity> newCollection, Consumer<TEntity> removeAction, Consumer<TEntity> addAction) {
        boolean changed = false;
        for (TEntity entity : difference(oldCollection, newCollection)) {
            removeAction.accept(entity);
            changed = true;
        }

        for (TEntity entity : difference(newCollection, oldCollection)) {
            addAction.accept(entity);
            changed = true;
        }

        return changed;
    }

    /**
     * Computes the difference {@code first - second} lazily.
     * <p>
     * The result is an {@link Iterable} that snapshots the elements of {@code first} and the
     * membership information of {@code second} once, when this method is called. Afterward,
     * further mutation of {@code first} or {@code second} does not affect the returned iterable
     * nor invalidate its iterator (no {@link java.util.ConcurrentModificationException} risk),
     * and no intermediate result collection is eagerly materialized.
     */
    public static <T> Iterable<T> difference(Collection<T> first, Collection<T> second) {
        List<T> firstSnapshot = List.copyOf(first);
        Set<T> secondSnapshot = second instanceof Set<T> set ? Set.copyOf(set) : Set.copyOf(new HashSet<>(second));
        return () -> {
            Iterator<T> it = firstSnapshot.iterator();
            return new Iterator<>() {
                private T next;
                private boolean hasNext = advance();

                private boolean advance() {
                    while (it.hasNext()) {
                        T candidate = it.next();
                        if (!secondSnapshot.contains(candidate)) {
                            next = candidate;
                            return true;
                        }
                    }
                    next = null;
                    return false;
                }

                @Override
                public boolean hasNext() {
                    return hasNext;
                }

                @Override
                public T next() {
                    if (!hasNext) {
                        throw new NoSuchElementException();
                    }
                    T result = next;
                    hasNext = advance();
                    return result;
                }
            };
        };
    }

    public static class MapHashComparator<T,Z> implements Comparator<Map<T,Z>> {

        @Override
        public int compare(Map<T, Z> o1, Map<T, Z> o2) {
            return Integer.compare(o1.hashCode(), o2.hashCode());
        }
    }

}

package de.teamlapen.sync;

import de.teamlapen.faction.api.util.FIdentifier;
import de.teamlapen.sync.api.IAttachmentSync;
import de.teamlapen.sync.properties.Property;
import net.minecraft.core.component.DataComponentMap;
import net.minecraft.core.component.DataComponentPatch;
import net.minecraft.core.component.DataComponentType;
import org.jetbrains.annotations.MustBeInvokedByOverriders;
import org.jspecify.annotations.Nullable;

/**
 * Represents a synchronization mechanism for attachments {@link net.neoforged.neoforge.attachment.AttachmentType} where
 * data is saved on disk and synchronized to the client.
 * <p>
 * This abstract class extends {@code PropertySync}, enabling it to track and handle
 * the synchronization of properties. Additionally, it implements {@code IAttachment},
 * providing methods for dealing with attached data specific to an entity.
 */
public abstract class AttachmentSync extends PropertySync implements IAttachmentSync {

    private final SimpleMutableDataComponentMap dataComponents = new SimpleMutableDataComponentMap(this);

    public void sync() {
        if (this.properties.stream().anyMatch(Property::hasChanged)) {
            asEntity().syncData(getType());
        }
    }

    @Override
    @MustBeInvokedByOverriders
    protected void registerProperties() {
        this.registerProperty(FIdentifier.mod("components")).subProperty(() -> this.dataComponents).register();
    }

    @Override
    public @Nullable <T> T set(DataComponentType<T> componentType, @Nullable T value) {
        return dataComponents.set(componentType, value);
    }

    @Override
    public @Nullable <T> T remove(DataComponentType<? extends T> componentType) {
        return dataComponents.remove(componentType);
    }

    @Override
    public void applyComponents(DataComponentPatch patch) {
        dataComponents.applyPatch(patch);
    }

    @Override
    public void applyComponents(DataComponentMap components) {
        dataComponents.setAll(components);
    }

    @Override
    public DataComponentMap getComponents() {
        return this.dataComponents;
    }
}

