package de.teamlapen.sync;

import de.teamlapen.sync.api.ISyncable;
import de.teamlapen.sync.properties.IProperty;
import de.teamlapen.sync.properties.Property;
import net.minecraft.resources.Identifier;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import net.neoforged.neoforge.common.util.ValueIOSerializable;
import org.jetbrains.annotations.ApiStatus;
import org.jetbrains.annotations.MustBeInvokedByOverriders;

import java.util.*;

/**
 * Base class for sync-able properties.
 * <p>
 * Handles registering, syncing ob properties
 * <p>
 * To make use of this class, you need to override {@link #registerProperties()}. In the implementation you can register properties.
 * <p>
 * Properties are registered using {@link #registerProperty(Identifier)}.
 * <p>
 * To handle property changes, override {@link #onPropertyChanged()}.
 */
public abstract class PropertySync implements ValueIOSerializable, ISyncable, IProperty {

    private final Map<Identifier, Property> propertiesMap = new HashMap<>();
    protected final Collection<Property> properties = Collections.unmodifiableCollection(propertiesMap.values());

    public PropertySync() {
        this.registerProperties();
    }

    /**
     * This method is called in the constructor of this class.
     * It should be used to register properties using {@link #registerProperty(Identifier)}
     */
    @ApiStatus.OverrideOnly
    protected void registerProperties() {

    }

    //<editor-fold desc="IProperty">

    @Override
    public int getStatus() {
        return Objects.hash(this.properties.stream().map(Property::getStatus).toList());
    }

    @Override
    public boolean hasClientSync() {
        return this.properties.stream().anyMatch(Property::hasClientSync);
    }

    @Override
    public boolean hasServerLoad() {
        return this.properties.stream().anyMatch(Property::hasServerLoad);
    }

    //</editor-fold>

    //<editor-fold desc="Properties">

    @ApiStatus.OverrideOnly
    protected void onPropertyChanged() {

    }

    public final void registerProperty(Property property) {
        this.propertiesMap.put(property.key(), property);
    }

    protected final Property.PropertyBuilder registerProperty(Identifier key) {
        return new Property.PropertyBuilder(this, key);
    }

    //</editor-fold>

    //<editor-fold desc="Serialization">

    @Override
    @MustBeInvokedByOverriders
    public void serialize(ValueOutput output) {
        for (Property syncProperty : this.properties) {
            if (syncProperty.hasServerLoad()) {
                syncProperty.storeValue(output, Property.StoreMode.FULL);
            }
        }
    }

    @Override
    @MustBeInvokedByOverriders
    public void deserialize(ValueInput input) {
        for (Property syncProperty : this.properties) {
            if (!syncProperty.hasServerLoad()) continue;
            syncProperty.loadServer(input);
        }

        onPropertyChanged();
    }

    @Override
    public final void serializeFullUpdate(ValueOutput output) {
        for (Property property : this.properties) {
            if (property.hasClientSync()) {
                property.store(output, Property.StoreMode.FULL_UPDATE);
            }
        }
    }

    @Override
    public final void serializeUpdate(ValueOutput output) {
        for (Property property : this.properties) {
            if (property.hasClientSync() && property.hasChanged()) {
                property.store(output, Property.StoreMode.UPDATE);
            }
        }
    }

    @Override
    public final boolean deserializeUpdate(ValueInput input) {
        boolean changed = false;
        for (Property property : this.properties) {
            if (property.hasClientSync()) {
                changed = property.loadClient(input) || changed;
            }
        }

        if (changed) {
            onPropertyChanged();
            return true;
        }
        return false;
    }

    //</editor-fold>
}

package de.teamlapen.sync.properties;

import com.google.common.base.Preconditions;
import org.jetbrains.annotations.Nullable;

import java.util.function.Consumer;
import java.util.function.Function;

public record DataApply<T>(@Nullable Consumer<T> serverFunction, @Nullable Function<T, Boolean> clientFunction) {


    static <T> DataApply<T> create(@Nullable Consumer<T> serverFunction, @Nullable Function<T, Boolean> clientFunction) {
        Preconditions.checkArgument(serverFunction != null || clientFunction != null, "Server or client function must be set");
        return new DataApply<>(serverFunction, clientFunction);
    }


    public void loadServer(T data) {
        if (this.serverFunction == null) return;
        this.serverFunction.accept(data);
    }

    public boolean loadClient(T data) {
        if (this.clientFunction == null) return false;
        return this.clientFunction.apply(data);
    }

    public boolean canLoadServer() {
        return this.serverFunction != null;
    }

    public boolean canLoadClient() {
        return this.clientFunction != null;
    }
}

package de.teamlapen.sync.properties;

import de.teamlapen.sync.PropertySync;
import net.minecraft.resources.Identifier;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;

import java.util.function.Supplier;

public class DeferredProperty<T extends PropertySync> extends Property {

    private final Supplier<T> property;
    private final boolean clientSync;
    private final boolean serverLoad;

    public DeferredProperty(Identifier key, Supplier<T> property, boolean clientSync, boolean serverLoad) {
        super(key);
        this.property = property;
        this.clientSync = clientSync;
        this.serverLoad = serverLoad;
    }

    @Override
    public boolean hasClientSync() {
        return this.clientSync;
    }

    @Override
    public boolean hasServerLoad() {
        return this.serverLoad;
    }

    @Override
    public boolean loadClient(ValueInput input) {
        return input.child(this.key.toString()).filter(this.property.get()::deserializeUpdate).isPresent();
    }

    @Override
    public void loadServer(ValueInput input) {
        this.property.get().deserialize(input.childOrEmpty(this.key.toString()));
    }

    @Override
    public int getStatus() {
        return this.property.get().getStatus();
    }

    @Override
    public int storeValue(ValueOutput output, StoreMode mode) {
        ValueOutput child = output.child(this.key.toString());
        switch (mode) {
            case FULL -> property.get().serialize(child);
            case FULL_UPDATE -> property.get().serializeFullUpdate(child);
            case UPDATE -> property.get().serializeUpdate(child);
        }
        return property.get().hashCode();
    }

    public static class Builder<T extends PropertySync> {

        private final PropertyBuilder propertySync;
        private final Supplier<T> property;
        private boolean clientSync = true;
        private boolean serverLoad = true;

        public Builder(PropertyBuilder propertySync, Supplier<T> property) {
            this.propertySync = propertySync;
            this.property = property;
        }

        public Builder<T> disableClientSync() {
            this.clientSync = false;
            return this;
        }

        public Builder<T> disableServerLoad() {
            this.serverLoad = false;
            return this;
        }

        public void register() {
            this.propertySync.register(key -> new DeferredProperty<>(key, this.property, this.clientSync, this.serverLoad));
        }
    }
}

package de.teamlapen.sync.properties;

import com.google.common.base.Preconditions;
import com.mojang.serialization.Codec;
import de.teamlapen.sync.PropertySync;
import net.minecraft.resources.Identifier;
import net.minecraft.util.StringRepresentable;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;

import java.util.*;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Supplier;

/**
 * Base class for sync-able properties / attributes
 */
public abstract class Property implements IProperty {

    protected final Identifier key;
    private int lastHash;

    public Property(Identifier key) {
        this.key = key;
    }

    /**
     * Unique key for this property.
     * <p>
     * Used as the key for serialization / deserialization of this property
     */
    public Identifier key() {
        return key;
    }

    @Override
    public abstract boolean hasClientSync();

    @Override
    public abstract boolean hasServerLoad();

    /**
     * Check if this property has changed since the last synchronization.
     * @return {@code true} if the property has changed, otherwise {@code false}
     */
    public boolean hasChanged() {
        return this.lastHash != getStatus();
    }

    /**
     * Stores this property into the output.
     * <p>
     * @implNote This automatically updates the status of this property, marking it as un-dirty.
     * @throws IllegalStateException if this method is called to store a property server side
     */
    public void store(ValueOutput output, StoreMode mode) {
        Preconditions.checkArgument(mode.client, "Can not store property server side with this method. This would modify the sync status");
        this.lastHash = storeValue(output, mode);
    }

    /**
     * Stores this property into the output.
     *
     * @implSpec This does not update the internal status of this property. For this call {@link #store(ValueOutput, StoreMode)} instead.
     *
     * @return The current status of the property
     */
    public abstract int storeValue(ValueOutput output, StoreMode mode);

    /**
     * Loads this property from the input.
     * @return {@code true} if the property has changed, otherwise {@code false}
     */
    public abstract boolean loadClient(ValueInput input);

    /**
     * Loads this property from the input.
     */
    public abstract void loadServer(ValueInput input);

    public enum StoreMode {
        /** Full storage on the server side to save the property to disk */
        FULL(true, false),
        /** Full storage of sync-able properties to send to new client players */
        FULL_UPDATE(false, true),
        /** Storage of dirty properties to send to all clients*/
        UPDATE(false, true);

        private final boolean server;
        private final boolean client;

        StoreMode(boolean server, boolean client) {
            this.server = server;
            this.client = client;
        }

        /**
         * Is allowed to store this property server side.
         */
        public boolean server() {
            return this.server;
        }

        /**
         * Is allowed to sync properties to the client.
         */
        public boolean isClient() {
            return this.client;
        }
    }

    public record PropertyBuilder(PropertySync propertySync, Identifier key) {

        public <T> SimpleProperty.Builder<T> simple(Codec<T> codec) {
            return new SimpleProperty.Builder<>(this, codec);
        }

        public <T> SimpleProperty.NullableBuilder<T> nullable(Codec<T> codec) {
            return new SimpleProperty.NullableBuilder<>(this, codec);
        }

        public <T> SimpleProperty.Builder<List<T>> list(Codec<T> codec) {
            return new SimpleProperty.Builder<>(this, codec.listOf()).defaultValue(ArrayList::new);
        }

        public <T, Z> SimpleProperty.Builder<Map<T,Z>> map(Codec<Map<T,Z>> codec) {
            return new SimpleProperty.Builder<>(this, codec).defaultValue(HashMap::new);
        }

        public <T> SimpleProperty.Builder<Set<T>> set(Codec<T> codec) {
            return new SimpleProperty.Builder<>(this, codec.listOf().xmap((Function<? super List<T>, Set<T>>) HashSet::new, ArrayList::new)).defaultValue(HashSet::new);
        }

        public <T extends PropertySync> DeferredProperty.Builder<T> subProperty(Supplier<T> propertySupplier) {
            return new DeferredProperty.Builder<>(this, propertySupplier);
        }

        public <T extends PropertySync> OptionalDeferredProperty.Builder<T> optionalSubProperty(Supplier<Optional<T>> propertySupplier) {
            return new OptionalDeferredProperty.Builder<>(this, propertySupplier);
        }

        public void simple(int defaultValue, Supplier<Integer> valueProvider, Consumer<Integer> valueSetter) {
            simple(Codec.INT).defaultValue(defaultValue).provider(valueProvider).commonLoader(x -> {
                int old = valueProvider.get();
                valueSetter.accept(x);
                return old != x;
            }).register();
        }

        public void simple(double defaultValue, Supplier<Double> valueProvider, Consumer<Double> valueSetter) {
            simple(Codec.DOUBLE).defaultValue(defaultValue).provider(valueProvider).commonLoader(x -> {
                double old = valueProvider.get();
                valueSetter.accept(x);
                return old != x;
            }).register();
        }

        public void simple(float defaultValue, Supplier<Float> valueProvider, Consumer<Float> valueSetter) {
            simple(Codec.FLOAT).defaultValue(defaultValue).provider(valueProvider).commonLoader(x -> {
                float old = valueProvider.get();
                valueSetter.accept(x);
                return old != x;
            }).register();
        }

        public void simple(boolean defaultValue, Supplier<Boolean> valueProvider, Consumer<Boolean> valueSetter) {
            simple(Codec.BOOL).defaultValue(defaultValue).provider(valueProvider).commonLoader(x -> {
                boolean old = valueProvider.get();
                valueSetter.accept(x);
                return old != x;
            }).register();
        }

        public void simple(String defaultValue, Supplier<String> valueProvider, Consumer<String> valueSetter) {
            simple(Codec.STRING).defaultValue(defaultValue).provider(valueProvider).commonLoader(x -> {
                String old = valueProvider.get();
                valueSetter.accept(x);
                return Objects.equals(old, x);
            }).register();
        }

        public <T extends Enum<T> & StringRepresentable> void simple(T defaultValue, Supplier<T> valueProvider, Consumer<T> valueSetter) {
            simple(StringRepresentable.fromEnum(() -> defaultValue.getDeclaringClass().getEnumConstants())).defaultValue(defaultValue).provider(valueProvider).commonLoader(x -> {
                T old = valueProvider.get();
                valueSetter.accept(x);
                return old != x;
            }).register();
        }

        public void simple(Identifier defaultValue, Supplier<Identifier> valueProvider, Consumer<Identifier> valueSetter) {
            simple(Identifier.CODEC).defaultValue(defaultValue).provider(valueProvider).commonLoader(x -> {
                var old = valueProvider.get();
                valueSetter.accept(x);
                return Objects.equals(old, x);
            }).register();
        }

        public void register(Function<Identifier,Property> property) {
            this.propertySync.registerProperty(property.apply(this.key));
        }
    }
}

package de.teamlapen.sync.properties;

import com.google.common.base.Preconditions;
import com.mojang.serialization.Codec;
import net.minecraft.resources.Identifier;
import net.minecraft.world.level.storage.ValueInput;
import net.minecraft.world.level.storage.ValueOutput;
import org.jetbrains.annotations.Nullable;

import java.util.Comparator;
import java.util.Optional;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Supplier;

public class SimpleProperty<T> extends Property {

    private final Codec<T> codec;
    private final Supplier<T> defaultValue;
    private final Supplier<T> valueProvider;
    private final DataApply<T> valueSetter;

    public SimpleProperty(Identifier key, Codec<T> codec, Supplier<T> defaultValue, Supplier<T> valueProvider, DataApply<T> valueSetter) {
        super(key);
        this.codec = codec;
        this.defaultValue = defaultValue;
        this.valueProvider = valueProvider;
        this.valueSetter = valueSetter;
    }

    @Override
    public boolean hasClientSync() {
        return this.valueSetter.canLoadClient();
    }

    @Override
    public boolean hasServerLoad() {
        return this.valueSetter.canLoadServer();
    }

    @Override
    public int getStatus() {
        return this.valueProvider.get().hashCode();
    }

    public int storeValue(ValueOutput output, StoreMode mode) {
        T t = this.valueProvider.get();
        output.store(this.key.toString(), this.codec, t);

        return t.hashCode();
    }

    public boolean loadClient(ValueInput input) {
        if (!this.valueSetter.canLoadClient()) return false;

        return input.read(this.key.toString(), this.codec).map(valueSetter::loadClient).orElse(false);
    }

    public void loadServer(ValueInput input) {
        if (!this.valueSetter.canLoadServer()) return;

        var value = input.read(this.key.toString(), this.codec).orElseGet(this.defaultValue);
        this.valueSetter.loadServer(value);
    }

    public static class Builder<T> {

        private final PropertyBuilder baseBuilder;
        private final Codec<T> codec;
        @Nullable
        private Supplier<T> defaultValue;
        @Nullable
        private Supplier<T> supplier;
        @Nullable
        private Consumer<T> serverLoader;
        @Nullable
        private Function<T, Boolean> clientLoader;
        @Nullable
        private Consumer<T> clientLoaderSimple;
        @Nullable
        private Comparator<T> comparator;

        public Builder(PropertyBuilder baseBuilder, Codec<T> codec) {
            this.baseBuilder = baseBuilder;
            this.codec = codec;
        }

        public Builder<T> defaultValue(T defaultValue) {
            this.defaultValue = () -> defaultValue;
            return this;
        }

        public Builder<T> defaultValue(Supplier<T> defaultValue) {
            this.defaultValue = defaultValue;
            return this;
        }

        public Builder<T> provider(Supplier<T> supplier) {
            this.supplier = supplier;
            return this;
        }

        public Builder<T> serverLoader(Consumer<T> loader) {
            this.serverLoader = loader;
            return this;
        }

        public Builder<T> clientLoader(Function<T, Boolean> loader) {
            this.clientLoader = loader;
            return this;
        }

        public Builder<T> commonLoader(Function<T, Boolean> loader) {
            this.serverLoader = loader::apply;
            this.clientLoader = loader;
            return this;
        }

        public Builder<T> commonLoader(Consumer<T> loader, Comparator<T> comparator) {
            this.serverLoader = loader;
            this.clientLoaderSimple = loader;
            this.comparator = comparator;
            return this;
        }

        public Builder<T> comparator(Comparator<T> comparator) {
            this.comparator = comparator;
            return this;
        }

        public void register() {
            Preconditions.checkArgument( this.defaultValue != null, "Default value must be set");
            Preconditions.checkArgument( this.supplier != null, "Supplier must be set");
            Preconditions.checkArgument( this.serverLoader != null ||  this.clientLoader != null, "Server or client loaders must be set");
            Preconditions.checkArgument(this.clientLoaderSimple == null || this.clientLoader == null, "Only one of clientLoader or clientLoaderSimple can be set");
            Preconditions.checkArgument(this.clientLoader != null || (this.clientLoaderSimple == null || this.comparator != null), "Comparator must be set if clientLoaderSimple is set");

            if (this.clientLoader != null && this.comparator != null) {
                this.clientLoader = value -> {
                    assert this.supplier != null;
                    assert this.clientLoader != null;
                    assert comparator != null;

                    T t = this.supplier.get();
                    this.clientLoader.apply(value);
                    return comparator.compare(t, value) != 0;
                };
            }

            if (this.clientLoaderSimple != null) {
                this.clientLoader = value -> {
                    assert this.supplier != null;
                    assert this.clientLoaderSimple != null;
                    assert comparator != null;

                    T t = this.supplier.get();
                    this.clientLoaderSimple.accept(value);
                    return comparator.compare(t, value) != 0;
                };
            }

            this.baseBuilder.register(key -> {
                assert this.defaultValue != null;
                assert this.supplier != null;
                return new SimpleProperty<>(key, this.codec, this.defaultValue, this.supplier, DataApply.create(serverLoader, clientLoader));
            });
        }


    }

    public static class NullableBuilder<T> {

        private final Builder<Optional<T>> innerBuilder;

        public NullableBuilder(PropertyBuilder baseBuilder, Codec<@Nullable T> codec) {
            this.innerBuilder = new Builder<>(baseBuilder,  Codec.optionalField("value", codec, true).codec()).defaultValue(Optional.empty());
        }

        public NullableBuilder<T> defaultValue(@Nullable T defaultValue) {
            this.innerBuilder.defaultValue(Optional.ofNullable(defaultValue));
            return this;
        }

        public NullableBuilder<T> defaultValue(Supplier<@Nullable T> defaultValue) {
            this.innerBuilder.defaultValue(() -> Optional.ofNullable(defaultValue.get()));
            return this;
        }

        public NullableBuilder<T> provider(Supplier<@Nullable T> supplier) {
            this.innerBuilder.provider(() -> Optional.ofNullable(supplier.get()));
            return this;
        }

        public NullableBuilder<T> serverLoader(Consumer<@Nullable T> loader) {
            this.innerBuilder.serverLoader(x -> loader.accept(x.orElse(null)));
            return this;
        }

        public NullableBuilder<T> clientLoader(Function<@Nullable T, Boolean> loader) {
            this.innerBuilder.clientLoader(x -> loader.apply(x.orElse(null)));
            return this;
        }

        public NullableBuilder<T> commonLoader(Function<@Nullable T, Boolean> loader) {
            this.innerBuilder.commonLoader(x -> loader.apply(x.orElse(null)));
            return this;
        }

        public NullableBuilder<T> commonLoader(Consumer<@Nullable T> loader, Comparator<Optional<T>> comparator) {
            this.innerBuilder.commonLoader(x -> loader.accept(x.orElse(null)), comparator);
            return this;
        }

        public NullableBuilder<T> comparator(Comparator<@Nullable T> comparator) {
            this.innerBuilder.comparator(new Comparator<>() {
                private final Comparator<@Nullable T> delegate = comparator;

                @Override
                public int compare(Optional<T> o1, Optional<T> o2) {
                    return delegate.compare(o1.orElse(null), o2.orElse(null));
                }
            });
            return this;
        }

        public void register() {
            this.innerBuilder.register();
        }
    }
}

